import Config

# For production, don't forget to configure the url host
# to something meaningful, Phoenix uses this information
# when generating URLs.
#
# Note we also include the path to a cache manifest
# containing the digested version of static files. This
# manifest is generated by the `mix phx.digest` task,
# which you should run after static files are built and
# before starting your production server.
port_ssl = System.get_env("HTTPS_PORT") || 8443
certfile = System.get_env("HTTPS_CERT_FILE") || "priv/cert/selfsigned.pem"
keyfile = System.get_env("HTTPS_KEY_FILE") || "priv/cert/selfsigned_key.pem"

config :schema_server, SchemaWeb.Endpoint,
  http: [port: System.get_env("PORT") || 8000],
  https: [
    port: port_ssl,
    cipher_suite: :strong,
    certfile: certfile,
    keyfile: keyfile
  ],
  url: [
    host: System.get_env("HOST") || "localhost",
    port: System.get_env("URL_PORT") || 8000,
    path: System.get_env("SCHEMA_WEB_PATH") || "/"
  ]

# Configures the locations of the schema files
config :schema_server, Schema.Application, schema_file: System.get_env("SCHEMA_FILE")
config :schema_server, Schema.Application, schemas_home: System.get_env("SCHEMAS_HOME")
